-- ============================================================
-- SEED EXT 5: Módulo 04 — Present Continuous (ex 178-248)
-- Novos tópicos: PC em TOEFL essays avançados, PC para tendências
-- em dados, PC em academic analysis, PC com always para crítica
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-continuous';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-continuous não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: PC para tendências em dados e análise
  (cid,51,178,'gap_fill','Income inequality _____ (rise) in most high-income countries, even as the rate of global extreme poverty _____ (fall) and emerging economy middle classes _____ (expand).','is rising / is falling / are expanding',NULL,'PC for ongoing trend contrasted across different dimensions.','easy'),
  (cid,51,179,'gap_fill','The data _____ (show) that urban populations _____ (grow) fastest in sub-Saharan Africa, while _____ (slow) significantly in parts of East Asia where fertility rates _____ (decline) steeply.','show / are growing / slowing / are declining',NULL,'PS for data-presentation + PC for current ongoing demographic trends.','medium'),
  (cid,51,180,'gap_fill','As renewable energy costs _____ (continue) _____ (fall), the economic case for maintaining existing fossil fuel infrastructure _____ (become) progressively harder _____ (defend).','continue / to fall / is becoming / to defend',NULL,'PC for ongoing trend + comparative dynamic.','medium'),
  (cid,51,181,'multiple_choice','Which sentence uses PC CORRECTLY to describe a trend visible in current data?','Global temperatures are rising at a rate that exceeds the most alarming projections made two decades ago.','["Global temperatures rise at a rate that exceeds alarming projections.","Global temperatures have risen at a rate that is exceeding alarming projections.","Global temperatures are rising at a rate that exceeds the most alarming projections made two decades ago.","Global temperatures were rising at a rate that exceeded alarming projections."]','PC ''are rising'' = current ongoing trend. PS ''exceeds'' = factual comparison.','easy'),
  (cid,51,182,'gap_fill','The labor market _____ (undergo) a fundamental transformation: traditional employment _____ (decline) in many sectors while freelance and platform-mediated work _____ (proliferate).','is undergoing / is declining / is proliferating',NULL,'PC for structural ongoing transformation across multiple sectors.','easy'),

  -- BLOCK 52: PC para mudanças graduais em políticas e sociedade
  (cid,52,183,'gap_fill','Attitudes toward climate change _____ (shift) in younger generations, who _____ (demonstrate) significantly higher levels of concern and _____ (demand) more ambitious policy responses than _____ (find/passive) in older cohorts.','are shifting / are demonstrating / are demanding / are found',NULL,'PC for generational attitude shift + PC for political behavior.','medium'),
  (cid,52,184,'gap_fill','The international rules-based order _____ (face) increasing strain as several major powers _____ (challenge) multilateral institutions and _____ (assert) competing visions of global governance.','is facing / are challenging / are asserting',NULL,'PC for current structural stress in international relations.','medium'),
  (cid,52,185,'gap_fill','The relationship between universities and the private sector _____ (transform) rapidly, with industry _____ (play) an increasingly significant role in research funding and _____ (shape) curriculum priorities.','is transforming / playing / shaping',NULL,'PC for transformation + gerund-participle for co-occurring processes.','hard'),
  (cid,52,186,'multiple_choice','Which sentence BEST describes a gradual social change using PC?','The boundaries between work and personal life are becoming increasingly blurred as digital connectivity extends the working day.','["The boundaries between work and personal life became increasingly blurred.","The boundaries between work and personal life are becoming increasingly blurred as digital connectivity extends the working day.","The boundaries between work and personal life have become increasingly blurred once.","The boundaries between work and personal life become increasingly blurred as connectivity extends."]','PC ''are becoming'' = gradual ongoing change. PS ''extends'' = factual mechanism.','easy'),
  (cid,52,187,'gap_fill','More countries _____ (recognize) the rights of LGBTQ+ individuals in their legal frameworks, though significant _____ (resist) _____ (persist) in some regions, and the pace of change _____ (vary) enormously across contexts.','are recognizing / resistance / persists / varies',NULL,'PC for trend + PS for factual observation + PS for factual variation.','medium'),

  -- BLOCK 53: PC com ''always'' para crítica (ironic/rhetorical)
  (cid,53,188,'gap_fill','Politicians _____ (always/promise) bold reform during election campaigns, only to _____ (discover) once in office that the constraints of coalition politics make comprehensive change _____ (far/difficult) than _____ (appear) in opposition.','are always promising / discover / far more difficult / it appeared',NULL,'''Are always promising'' = PC + always for criticism of repeated behavior pattern.','medium'),
  (cid,53,189,'gap_fill','Commentators _____ (always/predict) the imminent decline of this institution, yet it _____ (continue) _____ (adapt) and _____ (demonstrate) a resilience that _____ (consistently/defy) expectations.','are always predicting / continues / to adapt / demonstrates / consistently defies',NULL,'''Always predicting'' (PC critical) + PS for factual outcome.','medium'),
  (cid,53,190,'multiple_choice','What does PC with ''always'' typically express in formal academic commentary?','A habitual or repeated pattern that the writer considers excessive, irritating, or worth remarking upon.','["A single past event","A future intention","A habitual or repeated pattern that the writer considers excessive, irritating, or worth remarking upon.","A permanent scientific truth"]','''Always + PC'' = critical remark on habitual behavior, stronger than PS ''always does.''','medium'),
  (cid,53,191,'gap_fill','The media _____ (always/frame) complex policy questions as simple binary choices, _____ (make) it difficult for nuanced positions to _____ (receive) the public attention they _____ (deserve).','are always framing / making / receive / deserve',NULL,'''Always framing'' = PC critical pattern + participial result clause.','medium'),

  -- BLOCK 54: PC em negociações e processos em curso
  (cid,54,192,'gap_fill','Negotiators from both parties _____ (currently/work) toward a framework agreement, though significant differences _____ (remain) on the question of verification mechanisms.','are currently working / remain',NULL,'PC for active current process + PS for persistent factual gap.','easy'),
  (cid,54,193,'gap_fill','The World Trade Organization _____ (undergo) a process of reform, with member states _____ (debate) proposals for _____ (modernize) its dispute settlement system and _____ (update) its negotiating agenda.','is undergoing / debating / modernizing / updating',NULL,'PC for institutional reform process + gerunds for component activities.','medium'),
  (cid,54,194,'gap_fill','Several major pharmaceutical companies _____ (develop) next-generation mRNA vaccines for malaria and tuberculosis, and early clinical data _____ (suggest) promising results.','are developing / suggest',NULL,'PC for R&D activity in progress + PS for factual early data.','easy'),
  (cid,54,195,'multiple_choice','Which PC use is MOST APPROPRIATE for an academic paragraph on current geopolitics?','Tensions between the major powers are deepening, prompting concerns about the stability of the international order.','["Tensions between the major powers deepen, prompting concerns.","Tensions between the major powers are deepening, prompting concerns about the stability of the international order.","Tensions between the major powers have been deepening since ancient times.","Tensions between the major powers were deepening last year."]','PC ''are deepening'' = ongoing current dynamic with present relevance.','easy'),
  (cid,54,196,'gap_fill','The refugee situation at _____ border _____ (deteriorate) rapidly: new arrivals _____ (outnumber) _____ available _____ (shelter) capacity, and humanitarian agencies _____ (struggle) to _____ (meet) basic needs.','the / is deteriorating / are outnumbering / the / shelter / are struggling / meet',NULL,'PC for urgent ongoing humanitarian situation + ''available shelter'' (attributive adjective).','medium'),

  -- BLOCK 55: TOEFL Reading avançado com PC
  (cid,55,197,'multiple_choice','[TOEFL Reading] ''Researchers are questioning assumptions that have guided the field for decades.'' What does the PC ''are questioning'' communicate?','The questioning is an ongoing, current process — not a completed act.','["It happened once in the past","The questioning is an ongoing, current process — not a completed act.","It will happen in the future","It is a permanent scientific truth"]','PC = action in progress at this time (not completed, not habitual).','easy'),
  (cid,55,198,'gap_fill','[TOEFL Reading] ''As governments _____ (shift) policy priorities toward net zero, energy companies _____ (adapt) their business models accordingly, _____ (divest) from fossil assets and _____ (invest) in renewable capacity.'' Best forms?','shift / are adapting / divesting / investing',NULL,'PS for government action (factual) + PC for companies'' ongoing adaptation + participials.','hard'),
  (cid,55,199,'multiple_choice','[TOEFL Reading] ''The boundaries between academic disciplines are blurring as researchers increasingly collaborate across traditional field boundaries.'' The PC ''are blurring'' signals:','A gradual, ongoing change in the structure of academic knowledge that has not been completed.','["A sudden completed change","A gradual, ongoing change in the structure of academic knowledge that has not been completed.","A past historical event","A prediction about the future"]','PC = ongoing, progressive, not yet complete process.','easy'),

  -- BLOCK 56: TOEFL Speaking avançado com PC
  (cid,56,200,'production','[TOEFL Speaking — 45s] A reading argues that AI is transforming the job market. A lecture offers a more cautious view. Summarize using present continuous where appropriate.','',NULL,'The reading argues that artificial intelligence is fundamentally transforming the job market, with automation replacing routine tasks at a pace that is accelerating faster than labor markets can adapt. According to the reading, entire occupational categories are disappearing, and the workers most affected are finding it extremely difficult to retrain for the new skills that are becoming most valuable. However, the professor presents a more cautious interpretation of the evidence. She argues that while AI is certainly changing the content of many jobs — automating specific tasks within occupations rather than eliminating occupations wholesale — the data on net employment effects are considerably less alarming than the reading suggests. She notes that new forms of employment are also emerging alongside automation, and that the pace of job destruction so far has not exceeded the historical pace of job creation in new sectors. The professor concludes that the changes underway are real and significant, but that the reading''s framing overstates the degree of disruption currently occurring.','hard'),
  (cid,56,201,'production','[TOEFL Speaking — 45s] Discuss what is currently happening in international climate negotiations. Use PC throughout.','',NULL,'International climate negotiations are entering a critical phase as the gap between the commitments countries are making and the reductions in emissions that the science is requiring continues to widen. Major emitting countries are increasingly feeling pressure both from civil society organizations, which are demanding more ambitious action, and from the physical manifestations of climate change — the floods, droughts, and extreme heat events that are becoming more frequent and severe — which are making the urgency of action more politically salient. Negotiators are grappling with several unresolved issues: the question of how to finance adaptation in the most vulnerable countries is becoming more contentious as damages mount, and the debate over loss and damage compensation is intensifying. Some countries are showing encouraging signs of increased ambition in their nationally determined contributions, while others are struggling to maintain even their existing commitments in the face of economic pressures. The diplomatic architecture is holding, but the fundamental gap between commitments and the requirements of the Paris goals is growing rather than narrowing.','hard'),

  -- BLOCK 57: TOEFL Writing avançado com PC
  (cid,57,202,'production','[TOEFL Writing — 200 words] Write a paragraph on digital transformation in healthcare using PC throughout.','',NULL,'Healthcare is undergoing one of its most significant technological transformations in a generation as digital tools are becoming integrated into almost every dimension of clinical care and health system management. Electronic health records are replacing paper-based systems in most high-income countries, though interoperability — the ability of different systems to share information — remains a challenge that health systems are still working to resolve. Wearable devices are enabling continuous monitoring of vital signs and physiological parameters that previously required clinical visits, and the data these devices are generating are being analyzed by machine learning algorithms that are increasingly capable of identifying early signs of deterioration. Telemedicine platforms are extending the reach of specialist care to patients in remote areas and are reducing the barriers that distance and cost previously created. AI-assisted diagnostic tools are beginning to transform radiology, pathology, and genomics, supporting clinicians in identifying patterns that might otherwise be missed. However, health systems are also grappling with the equity implications of digital transformation: as care is moving toward digital channels, patients who lack digital literacy or device access are at risk of being left behind. The transformation is accelerating, and health systems that are not actively managing these implications may find that digital innovation is widening the health disparities they are trying to close.','hard'),
  (cid,57,203,'production','[TOEFL Writing — 200 words] Write a paragraph on changing patterns of global power using PC for current dynamics.','',NULL,'The international system is undergoing a profound reconfiguration as the unipolar moment that characterized the post-Cold War decades is giving way to a more complex multipolar order. China is consolidating its position as a comprehensive great power, extending its economic influence through infrastructure investment across Asia, Africa, and Latin America while simultaneously developing military capabilities that are challenging American dominance in the Indo-Pacific region. India is emerging as an increasingly significant player in global affairs, and its growing economic weight and technological capacity are earning it a more central role in the international institutions whose governance structures are also evolving. Russia is pursuing a revisionist agenda in its near abroad, challenging the territorial settlement of the post-Cold War period, though the economic consequences of international isolation following the invasion of Ukraine are limiting the resources available for this project. The transatlantic alliance is maintaining its cohesion despite internal tensions, and NATO is adapting its posture and capabilities in response to the changed security environment. International institutions are straining under these pressures, as the major power competition that is intensifying is complicating the multilateral cooperation that global challenges are requiring. Whether the international system is moving toward stable multipolarity or dangerous disorder is a question that analysts are debating with increasing urgency.','hard'),

  -- BLOCK 58: Final
  (cid,58,204,'production','[TOEFL Writing — 200 words] Write a paragraph on changing patterns of consumption and their environmental implications using PC.','',NULL,'Consumer behavior is changing in ways that have significant implications for the environmental footprint of high-income societies, though the pace and direction of change vary considerably across product categories and demographic groups. In some domains, more sustainable patterns are clearly emerging: electric vehicle adoption is accelerating, plant-based food consumption is growing, and renewable energy is attracting increasing consumer investment through rooftop solar and green tariff options. However, in other domains, less encouraging trends are persisting: fast fashion consumption continues to grow globally despite increasing awareness of its environmental impact, air travel is recovering rapidly from the pandemic disruption and is approaching pre-pandemic levels, and the volume of consumer electronics is increasing as replacement cycles are shortening and device ownership is expanding into new global markets. The relationship between consumer choice and sustainability is also being complicated by the political contestation of green products and lifestyle choices in some countries, where sustainable consumption is becoming associated with particular political identities rather than being treated as a broad social norm. The question of whether individual consumer behavior change or structural transformation of production systems is the more powerful lever for reducing environmental impact is being debated by researchers and policymakers simultaneously, and the answer is likely that both are necessary but neither alone is sufficient.','hard'),
  (cid,58,205,'production','[TOEFL Speaking — 60s] Discuss what is happening in the global education system right now. Use PC throughout.','',NULL,'Global education systems are undergoing simultaneous changes along multiple dimensions, and the pace of transformation is accelerating in ways that are creating both opportunities and significant challenges for policymakers. The rapid diffusion of digital learning tools is enabling forms of personalized instruction that traditional classroom settings are struggling to replicate, and AI-powered tutoring systems are beginning to provide the kind of adaptive feedback that has previously required individual human tutors. At the same time, foundational learning outcomes are declining in several high-income countries following the disruption of the COVID-19 pandemic, and systems are still working to recover the learning losses that accumulated during school closures. Access to education is improving globally — primary enrollment is approaching universal levels — but quality is not keeping pace with enrollment growth in many contexts, and children in low-income countries are attending school without acquiring the basic literacy and numeracy skills that education systems are supposed to deliver. Demographic shifts are also reshaping education demand: in countries where fertility rates are falling, declining student numbers are creating financial and organizational challenges for institutions that are accustomed to growing intake. Universities in particular are competing for international students whose numbers are becoming increasingly central to institutional financial sustainability, while domestic political debates about immigration are complicating student mobility. The result is a global education landscape that is changing faster than the governance frameworks that are supposed to manage it.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
